<script setup lang="ts">
import { t } from '@/i18n'
import { say } from '@/content/portfolio'
import { useAgent } from '@/services/agent'
import { computed, ref } from 'vue'
const { facts, factsSaving, factsNotice, factsTab, addition, saveFacts, addFacts, regenerate, prompt, jobTitle, companyName, run, history, resume, parsedText, custom, resumeDialog,
  fileUrl, fileError, notice, busy, working, uploading, saving, ready, tab, mobileTab, paused, active,
  fileName, isPdf, currentTitle, pending, statusLabel, openResume, initialize, openTask, execute,
  send, pickFile, confirmResume, clearFile, reset, saveCustom, decide, download, startInterview } = useAgent()
const tabs = ['Role analysis', 'Tailored CV', 'Interview preparation']
const examples = ['AI Application Engineer', 'Product Manager', 'Front-end Developer']
const paperPreview = ref(false)
const missingPrompts = computed(() => (custom.value?.missing_information_warnings || []).map(text => text
  .replace(/主简历中未明确体现|主简历中未体现/g, say('You can add', '可补充'))
  .replace(/[，,；;]?不能直接添加[。.]?/g, say(': If you have relevant practical experience, add your tasks, contribution and real results; otherwise, skip this.', '：如有相关实践，请补充具体任务、你的贡献和真实结果；没有可跳过。'))))
const factCount = computed(() => [facts.value.about, facts.value.skills, facts.value.experiences].filter(Boolean).length)
const suggestionSections = computed(() => (custom.value?.sections || []).map(s => ({ ...s, items: s.items.filter(i => i.has_suggestion) })).filter(s => s.items.length))
const suggestionCount = computed(() => suggestionSections.value.reduce((n, s) => n + s.items.length, 0))
const question = computed(() => run.value?.status === 'waiting' ? [...run.value.messages].reverse().find(m => m.role === 'assistant')?.content : '')
const resultReady = computed(() => tab.value === 'Role analysis' ? !!run.value?.match : tab.value === 'Tailored CV' ? !!custom.value : !!run.value?.preparation)
</script>

<template>
  <div class="agent-shell">
    <aside class="agent-rail">
      <a class="agent-brand" href="/" :title="t('Return to the three entry points')"><span class="agent-mark">↗</span><span>{{ t("Zhitu CV") }}<small>{{ t("YOUR NEXT CHAPTER") }}</small></span></a>
      <button class="agent-new" :disabled="working || saving" @click="reset"><span>＋</span> {{ t("New career task") }}</button>
      <a class="workspace-back" href="/">{{ t("← Back to AI Studio") }}</a><div class="agent-nav-label">{{ t("Workspace") }}</div>
      <button class="agent-nav selected" @click="mobileTab = 'Chat'"><span>◈</span> {{ t("Career Agent") }} <i>{{ t("NEW") }}</i></button>
      <button class="agent-nav" @click="openResume"><span>▤</span> {{ t("My CV") }}</button>
      <div class="agent-nav-label history-label">{{ t("Recent tasks") }}</div>
      <div class="agent-history-list"><button v-for="task in history" :key="task.id" class="agent-history" :class="{ 'task-selected': task.id === run?.id }" :disabled="working || saving" :title="t(task.title)" @click="openTask(task.id)">{{ t(task.title) }}</button></div>
      <p v-if="!history.length" class="agent-empty-history">{{ t("Every new opportunity") }}<br />{{ t("starts with a goal.") }}</p>
      <div class="facts-mini"><span>{{ t("YOUR STORY") }}</span><strong>{{ t("Beyond a one-page CV") }}</strong><p>{{ t(factCount) }} {{ t("experience categories added") }}<br />{{ t("Find the right highlights for each role.") }}</p><button @click="factsTab = 'Additional experience'; openResume()">{{ t("Add to my profile ↗") }}</button></div><div class="agent-rail-bottom"><span class="guest-avatar">{{ t("G") }}</span><div>{{ t("Guest workspace") }}<small>{{ t("Continue in this browser") }}</small></div></div>
    </aside>
    <main class="agent-main">
      <header class="agent-header"><div><span class="agent-breadcrumb">{{ t("Workspace /") }}</span> {{ t(currentTitle) }}</div><span class="agent-preview-badge">{{ t(ready ? 'Guest mode · Auto-save' : 'Connecting to workspace') }}</span></header>
      <div v-if="notice" class="agent-notice global-notice" role="status">{{ t(notice) }}<button v-if="!ready" @click="initialize">{{ t("Reconnect") }}</button><button :aria-label="t('Close tip')" @click="notice = ''">×</button></div>
      <div class="agent-mobile-tabs"><button v-for="item in ['Chat', 'Results']" :key="item" :class="{ chosen: mobileTab === item }" @click="mobileTab = item">{{ t(item) }}</button><button @click="openResume">{{ t("My CV") }}</button><button :disabled="working" @click="reset">{{ t("New task") }}</button></div>
      <select class="mobile-history" :aria-label="t('Recent tasks')" :value="run?.id || ''" :disabled="working" @change="openTask(($event.target as HTMLSelectElement).value)"><option value="" disabled>{{ t("Recent tasks") }}</option><option v-for="task in history" :key="task.id" :value="task.id">{{ t(task.title) }}</option></select>
      <div class="agent-columns" :class="{ 'show-results': mobileTab === 'Results', 'has-task': active }">
        <section class="agent-conversation">
          <div v-if="!active" class="agent-welcome">
            <span class="agent-kicker"><span></span> {{ t("A LITTLE PREPARATION. A BIG NEXT STEP.") }}</span>
            <h1>{{ t("Your next step.") }}<br /><span>{{ t("Which role are you aiming for?") }}</span></h1>
            <p>{{ t("Bring your experience and a target role.") }}<br />{{ t("Get a clearer match, a tailored CV and an interview preparation plan.") }}</p>
            <a href="/demo" class="agent-example-link">{{ say('Just exploring? View a complete example — no upload needed.', '先看看效果？查看完整示例，无需上传资料。') }} ↗</a>
            <div class="agent-suggestions"><button v-for="(example, index) in examples" :key="example" @click="jobTitle = t(example)"><span>0{{ t(index + 1) }}</span>{{ t(example) }}<b>↗</b></button></div>
          </div>
          <div v-else-if="run" class="agent-thread">
            <div class="agent-task-label">{{ t("This target") }} <span>{{ t(statusLabel) }}</span></div>
            <h2>{{ t(run.title) }}</h2>
            <div v-if="run.generic_requirements" class="agent-notice">{{ t("No complete JD was provided, so general job advice is used this time and does not represent the company's actual recruitment requirements.") }}</div>
            <div v-if="question" class="agent-question"><h3>{{ t("We just need a little more information from you") }}</h3><p>{{ t(question) }}</p></div>
            <div v-if="run.error" class="resume-file-error" role="alert">{{ t(run.error) }}</div>
            <button v-if="!working && ['ready', 'failed', 'running'].includes(run.status)" class="agent-result-action" @click="execute">{{ t(run.status === 'failed' ? 'Try again' : 'Continue preparing') }} →</button>
            <button v-if="!working" class="refresh-facts-button" @click="regenerate">{{ t("Regenerate with the latest information ↗") }}</button>
            <p v-if="run.status === 'completed'" class="completion-note">{{ t("Your career results are ready. View the results below, and once you have confirmed your CV you can download it.") }}</p>
          </div>
          <div v-if="!run || run.status === 'waiting'" class="agent-composer-wrap">
            <form v-if="!run || run.status === 'waiting'" class="agent-composer" @submit.prevent="send">
              <div v-if="!run" class="agent-job-fields"><label>{{ t("Job title *") }}<input v-model="jobTitle" required minlength="2" maxlength="100" :placeholder="t('For example: AI Application Development Engineer')" /></label><label>{{ t("Company name") }}<input v-model="companyName" maxlength="100" :placeholder="t('Optional, e.g. Xiaomi')" /></label></div>
              <label class="agent-sr" for="agent-prompt">{{ t(run ? 'Additional information' : 'Job requirements') }}</label><textarea id="agent-prompt" v-model="prompt" :maxlength="run ? 5000 : 20000" :placeholder="t(run ? 'Answer the follow-up question above…' : 'Paste the job requirements (optional) to make the analysis more accurate…')" rows="3"></textarea>
              <div class="agent-composer-actions"><button type="button" class="resume-open-button" @click="openResume">＋ {{ t(fileName || 'Add CV') }}</button><button class="agent-send" type="submit" :disabled="!ready || working || uploading || (run ? !prompt.trim() : jobTitle.trim().length < 2)" :aria-label="t('Start or continue a job search task')">↑</button></div>
            </form>
            <p class="agent-composer-hint">{{ t("CVs and tasks are stored privately · If cookies are cleared or the guest session expires, they cannot be recovered, so download your results promptly") }}</p>
          </div>
        </section>
        <div v-if="working" class="analysis-wait" role="status" aria-live="polite">
          <span class="analysis-orbit" aria-hidden="true">✧</span>
          <div><h3>{{ t("Preparing your job search results") }}<span class="waiting-dots" aria-hidden="true">…</span></h3><p>{{ t("This takes a little time; completed results will appear below. No need to submit again.") }}</p></div>
          <button v-if="busy" @click="paused = true" :disabled="paused">{{ t(paused ? 'Pause after completing the current process' : 'Pause further preparation') }}</button>
        </div>
        <aside class="agent-results">
          <div class="agent-results-heading"><div><span class="agent-kicker">{{ t("YOUR CAREER KIT") }}</span><h2>{{ t(active ? 'Your career results' : 'Every step brings results') }}</h2></div><span class="agent-kit-icon">✳</span></div>
          <template v-if="!active">
            <div class="agent-paper-scene"><div class="agent-paper"><div class="paper-top"><b>{{ t("Your next step") }}</b><span>{{ t("RESUME") }}</span></div><div class="paper-name">{{ t("Present yourself more clearly.") }}</div><i></i><i></i><div class="paper-section">{{ t("Experience · Ability · Potential") }}</div><i></i><i></i><i></i><div class="paper-section">{{ t("Prepared for the target role") }}</div><i></i><i></i></div><span class="agent-paper-tag">{{ t("✧ Real experience, precise expression") }}</span></div>
            <div class="agent-outcomes"><div><span class="outcome-icon peach">◎</span><div><h3>{{ t("See how you match the role") }}</h3><p>{{ t("Identify your strengths and the areas that need improvement.") }}</p></div></div><div><span class="outcome-icon mint">▤</span><div><h3>{{ t("Take away a finished CV") }}</h3><p>{{ t("Customised for the role, supports PDF and Word export.") }}</p></div></div><div><span class="outcome-icon lilac">✧</span><div><h3>{{ t("Prepare for interviews with direction") }}</h3><p>{{ t("Key knowledge, project follow-up questions and answer approaches.") }}</p></div></div></div>
            <div class="agent-side-note">{{ t("Go at your own pace.") }}<br /><span>{{ t("Once the preparation plan is complete, you can choose to do a mock interview.") }}</span></div>
          </template>
          <template v-else-if="run">
            <div class="agent-result-tabs" role="tablist" :aria-label="t('Job search outcomes')"><button v-for="item in tabs" :key="item" role="tab" :aria-selected="tab === item" :class="{ chosen: tab === item }" @click="tab = item">{{ t(item) }}</button></div>
            <div v-if="!resultReady" class="result-placeholder" :aria-busy="working">
              <template v-if="working"><div class="result-skeleton" aria-hidden="true"><i></i><i></i><i></i></div><h3>{{ t(tab) }}{{ t("Preparing") }}</h3><p>{{ t("It will appear automatically when ready, no need to refresh.") }}</p></template>
              <template v-else><h3>{{ t(tab) }}{{ t("Not yet generated") }}</h3><p>{{ t(run.status === 'waiting' ? 'Continue after adding the information above.' : 'Once you continue the task, the results will be shown here.') }}</p></template>
            </div>
            <div v-else-if="tab === 'Role analysis'" class="agent-result-content">
              <template v-if="run.match"><h3>{{ t(run.job_title) }} {{ t("· Role analysis") }}</h3><p v-if="!run.generic_requirements">{{ t("Reference match score:") }}{{ t(run.match.match_score) }} / 100</p><p>{{ t(run.match.verdict_reason) }}</p>
                <h4>{{ t("Role focus") }}</h4><ul><li v-for="item in run.match.key_requirements" :key="item.requirement">{{ t(item.requirement) }}</li></ul>
                <div v-for="item in run.match.matched_items" :key="item.requirement" class="agent-insight"><small>{{ t("Your strengths ·") }} {{ t(item.requirement) }}</small><p>{{ t(item.resume_evidence) }}</p></div>
                <h4>{{ t("More information needed") }}</h4><p v-for="item in run.match.missing_items" :key="item.requirement">{{ t(item.requirement) }}：{{ t(item.explanation) }}</p><h4>{{ t("Suggested next step") }}</h4><ul><li v-for="item in run.match.improvements" :key="item">{{ t(item) }}</li></ul>
              </template><p v-else>{{ t("Once the job analysis is complete, the real results will be shown here.") }}</p>
            </div>
            <div v-else-if="tab === 'Tailored CV'" class="agent-result-content">
              <template v-if="custom"><h3>{{ t("Confirm your wording and keep it real") }}</h3><p>{{ t("Total") }} {{ t(suggestionCount) }} {{ t("valid suggestions,") }}{{ t(pending) }} {{ t("items to confirm. Unrevised content has been kept in the full CV.") }}</p><label class="agent-editor-label">{{ t("Name *") }}<input v-model="custom.header.name" maxlength="40" /></label>
                <div class="agent-job-fields"><label>{{ t("Phone") }}<input v-model="custom.header.phone" maxlength="50" /></label><label>{{ t("Email") }}<input v-model="custom.header.email" maxlength="100" /></label></div>
                <button class="resume-open-button" @click="paperPreview = !paperPreview">{{ t(paperPreview ? 'View revision suggestions' : 'View / edit full CV') }}</button>
                <div v-if="paperPreview" class="agent-live-paper"><h2>{{ t(custom.header.name || 'Please enter your name') }}</h2><p>{{ t(custom.header.phone) }}　{{ t(custom.header.email) }}</p><section v-for="section in custom.sections" :key="section.title"><h3>{{ t(section.title) }}</h3><textarea v-for="(item, index) in section.items" :key="index" v-model="item.final_text" class="paper-text-editor" :aria-label="t(section.title + 'Body' + (index + 1))" maxlength="2000" rows="2" @input="item.decision = 'custom'"></textarea></section></div>
                <template v-else><p v-if="!suggestionCount" class="no-change-note">{{ t("There are currently no substantive rewrites for you to confirm. The original text has been retained; you can edit and export it in View / edit full CV.") }}</p><section v-for="(section, si) in suggestionSections" :key="si"><h4>{{ t(section.title) }}</h4><div v-for="(item, ii) in section.items" :key="ii" class="agent-edit-item"><div class="suggestion-comparison"><div><small>{{ t(item.source_kind === 'supplement' ? 'From supplementary material · suggested addition' : 'Original text') }}</small><p>{{ t(item.source_text) }}</p></div><div><small>{{ t("Suggested wording") }}</small><p>{{ t(item.suggested_text) }}</p></div></div><small>{{ t(item.reason) }}</small><div class="agent-downloads"><button @click="decide(item, 'accepted')">{{ t("Adopt suggestion") }}</button><button @click="decide(item, 'rejected')">{{ t(item.source_kind === 'supplement' ? 'Skip for now' : 'Keep original') }}</button></div><textarea v-model="item.final_text" class="agent-resume-editor" :aria-label="t(section.title + 'Final content' + (ii + 1))" maxlength="2000" rows="3" @input="item.decision = 'custom'"></textarea><small>{{ t(item.decision === 'pending' ? 'To confirm' : 'Confirmed') }}</small></div></section></template>
                <section class="facts-opportunity">
                  <span class="agent-kicker">{{ t("MAKE YOUR EXPERIENCE COUNT") }}</span>
                  <h3>{{ t(missingPrompts.length ? 'These experiences may not be on your CV yet' : 'Any other experience worth showcasing?') }}</h3>
                  <p>{{ t("A CV is not the whole picture. If you have relevant skills, course projects, internships or work experience, add real details and you can customise it again; if not, skip this.") }}</p>
                  <ul v-if="missingPrompts.length"><li v-for="hint in missingPrompts" :key="hint">{{ t(hint) }}</li></ul>
                  <label class="agent-editor-label">{{ t("Add job-related experience") }}<textarea v-model="addition" class="agent-resume-editor" maxlength="3000" rows="4" :disabled="working || factsSaving" :placeholder="t('For example: at what time, in what project, with what tools did you complete what work? Which part were you responsible for? What verifiable results were there? There is no need to fill in experience you do not have.')"></textarea></label>
                  <small>{{ t("Save to your experience library so it can also be used for future role tasks. The original output is retained; regenerating will create a new version.") }}</small>
                  <p v-if="factsNotice" role="status">{{ t(factsNotice) }}</p>
                  <div class="facts-actions"><button :disabled="working || factsSaving || !addition.trim()" @click="addFacts">{{ t(factsSaving ? 'Saving…' : 'Save experience only') }}</button><button :disabled="working || factsSaving" @click="regenerate">{{ t("Save additions and regenerate ↗") }}</button><button @click="factsTab = 'Additional experience'; openResume()">{{ t("Manage all materials") }}</button></div>
                </section>
                <button class="agent-result-action" :disabled="saving" @click="saveCustom">{{ t(saving ? 'Saving…' : 'Save changes') }}</button>
                <div class="agent-downloads"><button :disabled="saving || pending > 0 || !custom.header.name.trim()" @click="download('pdf')">{{ t("↓ PDF") }}</button><button :disabled="saving || pending > 0 || !custom.header.name.trim()" @click="download('word')">{{ t("↓ Word") }}</button></div>
              </template><p v-else>{{ t("Once the customised CV is complete, you can confirm, edit and export it here.") }}</p>
            </div>
            <div v-else class="agent-result-content"><template v-if="run.preparation"><h3>{{ t("Prepare for your next interview") }}</h3><p>{{ t(run.preparation.summary) }}</p><div v-for="(item, index) in run.preparation.items" :key="index" class="agent-prep-item"><span>0{{ t(index + 1) }}</span><div><h4>{{ t(item.title) }}</h4><p>{{ t(item.focus) }}</p><h4>{{ t(item.question) }}</h4><ul><li v-for="point in item.outline" :key="point">{{ t(point) }}</li></ul></div></div><div class="agent-interview-option"><h4>{{ t("Ready, let's do another mock interview") }}</h4><p>{{ t("You need to answer each question; you can start later.") }}</p><button @click="startInterview">{{ t("Start mock interview →") }}</button></div></template><p v-else>{{ t("Once the interview preparation plan is complete, it will be shown here. The mock interview will not start automatically.") }}</p></div>
          </template>
        </aside>
      </div>
    </main>
    <dialog ref="resumeDialog" class="agent-resume-dialog" aria-labelledby="resume-dialog-title" @click="($event.target === resumeDialog) && resumeDialog?.close()">
      <div class="resume-dialog-header"><div><span class="agent-kicker">{{ t("YOUR EXPERIENCE") }}</span><h2 id="resume-dialog-title">{{ t("My CV") }}</h2></div><button autofocus :aria-label="t('Close my CV')" @click="resumeDialog?.close()">×</button></div>
      <div class="agent-result-tabs"><button v-for="item in ['CV file', 'Additional experience']" :key="item" :class="{ chosen: factsTab === item }" @click="factsTab = item">{{ t(item) }}</button></div>
      <section v-if="factsTab === 'Additional experience'" class="facts-library">
        <h3>{{ t("Record what will not fit on a one-page CV") }}</h3>
        <p>{{ t("The content here feeds into role analysis, customised CVs and interview preparation. Only enter real information; do not enter sensitive details such as ID numbers or account passwords.") }}</p>
        <label>{{ t("Additional background") }} <small>{{ t(facts.about.length) }} / 1500</small><textarea v-model="facts.about" maxlength="1500" rows="3" :disabled="working || factsSaving" :placeholder="t('Information not included in the CV, such as specialism, course background, certificates and language skills')"></textarea></label>
        <label>{{ t("Skills and proficiency") }} <small>{{ t(facts.skills.length) }} / 3500</small><textarea v-model="facts.skills" maxlength="3500" rows="4" :disabled="working || factsSaving" :placeholder="t('Which tools or skills do you have? In which situations have you actually used them? Please distinguish between familiar, currently learning and proficient.')"></textarea></label>
        <label>{{ t("Projects, internships and practical experience") }} <small>{{ t(facts.experiences.length) }} / 10000</small><textarea v-model="facts.experiences" maxlength="10000" rows="7" :disabled="working || factsSaving" :placeholder="t('For each experience, write: dates and name → your role → what you did → skills used → real outcomes. Course projects, societies and volunteering also count.')"></textarea></label>
        <p v-if="factsNotice" role="status">{{ t(factsNotice) }}</p>
        <button class="agent-result-action" :disabled="working || factsSaving" @click="saveFacts">{{ t(factsSaving ? 'Saving…' : 'Save profile') }}</button>
        <p>{{ t("Existing results will not be changed automatically. After saving, you can return to the task and click Regenerate with latest materials.") }}</p>
      </section>
      <template v-else>
      <p class="resume-dialog-description">{{ t("After uploading, check the parsed text to confirm it accurately reflects your real experience.") }}</p>
      <p v-if="fileError" class="resume-file-error" role="alert">{{ t(fileError) }}</p>
      <label class="resume-upload-zone"><strong>{{ t(uploading ? 'Processing CV…' : resume ? 'Replace CV' : '+ Select your CV') }}</strong><span>{{ t("PDF / DOCX · max 10 MB") }}</span><input type="file" accept=".pdf,.docx" :disabled="working || uploading || !ready" @change="pickFile" /></label>
      <template v-if="resume">
        <div class="resume-file-info"><div><strong>{{ t(fileName) }}</strong><small>{{ t((resume.size_bytes / 1024).toFixed(1)) }} {{ t("KB · saved privately") }}</small></div><button :disabled="working || uploading" @click="clearFile">{{ t("Delete") }}</button></div>
        <iframe v-if="isPdf && fileUrl" :src="fileUrl" :title="t('Original PDF CV preview')" class="resume-pdf-preview"></iframe>
        <label class="agent-editor-label" for="parsed-resume">{{ t("Check and correct CV text") }}</label><textarea id="parsed-resume" class="agent-resume-editor" v-model="parsedText" rows="12" :disabled="working || uploading"></textarea>
        <div class="resume-dialog-actions"><a v-if="fileUrl" :href="fileUrl" :download="fileName">{{ t("Download original file") }}</a><button :disabled="working || uploading" @click="confirmResume">{{ t("Confirm text and save CV →") }}</button></div>
      </template>
      </template>
      <p class="resume-local-note">{{ t("You can continue using it in the same browser. After changing devices or clearing cookies, the original guest materials cannot be accessed.") }}</p>
    </dialog>
  </div>
</template>

